CREATE TABLE IF NOT EXISTS gis_payload_import_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL, payload_url text NOT NULL, payload_format text NOT NULL DEFAULT 'geojson', status text NOT NULL DEFAULT 'Started', http_status integer, feature_count integer NOT NULL DEFAULT 0, valid_geometry_count integer NOT NULL DEFAULT 0, hashed_feature_count integer NOT NULL DEFAULT 0, code_validated_count integer NOT NULL DEFAULT 0, error_count integer NOT NULL DEFAULT 0, content_hash text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS gis_payload_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), import_run_id uuid NOT NULL REFERENCES gis_payload_import_runs(id) ON DELETE CASCADE, dataset_id uuid NOT NULL, source_feature_id text, area_code text, area_name text, parent_area_code text, geometry_type text NOT NULL, geometry_json jsonb NOT NULL, feature_hash text NOT NULL, geometry_valid boolean NOT NULL DEFAULT false, code_valid boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_payload_runs_dataset ON gis_payload_import_runs(dataset_id,started_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_payload_features_run ON gis_payload_features(import_run_id);
CREATE INDEX IF NOT EXISTS idx_gis_payload_features_code ON gis_payload_features(dataset_id,area_code);